def lire_config(texte):
    config = {}
    for ligne in texte.split("\n"):
        ligne = ligne.strip()
        if not ligne or ligne.startswith("#"):
            continue
        cle, valeur = ligne.split("=", 1)
        config[cle.strip()] = valeur.strip()
    return config

def conflits(adresses):
    par_ip = {}
    for machine, ip in adresses.items():
        par_ip.setdefault(ip, []).append(machine)
    return sorted(ip + " : " + ", ".join(sorted(m)) for ip, m in par_ip.items() if len(m) > 1)

