def audit(configs):
    lignes = []
    par_ip = {}
    for machine in sorted(configs):
        config = lire_config(configs[machine])
        for probleme in verifier(config):
            lignes.append(machine + " : " + probleme)
        if "adresse" in config:
            par_ip.setdefault(config["adresse"], []).append(machine)
    for ip in sorted(par_ip):
        if len(par_ip[ip]) > 1:
            lignes.append("conflit " + ip + " : " + ", ".join(sorted(par_ip[ip])))
    return lignes
